inputs.default:
{
  "name": "orders-client",
  "enabled": true,
  "timeouts": {
    "connect": 5,
    "read": 30,
    "total": null
  },
  "retry": {
    "attempts": 3,
    "backoffMs": 200,
    "multiplier": 2.0,
    "jitter": false,
    "on": ["502", "503", "504"]
  },
  "pool": {
    "maxIdle": 16,
    "maxPerHost": 64,
    "idleTimeout": 90
  },
  "tls": {
    "verify": true,
    "minVersion": "1.2",
    "alpn": ["h2", "http/1.1"]
  },
  "headers": {
    "user-agent": "orders-client/4.1",
    "accept": "application/json",
    "x-request-budget-ms": 2500
  },
  "proxy": null,
  "logging": {
    "level": "warn",
    "redact": ["authorization", "cookie"],
    "sampleRate": 0.05
  },
  "aVeryLongKeyThatForcesTheLineToWrapInsideTheTextareaSoSoftWrapPositionsCanBeCompared": "value with spaces that also wraps across the visible width of the field"
}
